def main():
 d=json.load(open(STATE/'data/turnout/priority-set.json'));assert [x[0] for x in CONFIG]==[x['name'] for x in d['all_unit_order'][:22]]
 geo=json.load(open(ROOT/'geometry-summary.json'))['sources'];pdf=json.load(open(ROOT/'pdf-render-validation.json'));pdfs={x['source_id']:x for x in pdf['PDFs']};receipts={json.load(open(p))['source_id']:json.load(open(p)) for p in (ROOT/'raw').glob('*.receipt.json')};inventory=[];ledger=[]
 for r in receipts.values():
  b=body(r['source_id']);assert sha(b)==r['original_sha256'] and len(b)==r['original_bytes'];ledger.append(r)
 json_dump=lambda p,o:p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n')
 json_dump(ROOT/'source-ledger.json',{'scope':'Exact original/error HTTP entities and immutable shared-original references; each receipt retains available URL, redirects, status, headers, UTC retrieval, encoding and original/stored hashes. Shared acquisition fields absent from supplied receipts remain null; full coordinator entries are embedded and bodies reused read-only, without depending on mutable aggregate manifests. source_clock null means not assigned, never zero. Source edit/print/PDF/HTTP clocks are separate below.','sources':ledger,'native_geometry_clocks':{k:{x:v.get(x) for x in ['source_editingInfo','dateFieldsTimeReference']} for k,v in geo.items()},'PDF_clocks':{k:v['metadata'] for k,v in pdfs.items()},'web_reader_evidence':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p.read_bytes()),'file_written_utc':datetime.datetime.fromtimestamp(p.stat().st_mtime,datetime.timezone.utc).isoformat(),'scope':'Web-reader returned text/provenance; not original HTTP bytes, headers, or proof of direct download success.'} for p in sorted((ROOT/'raw').glob('*.web-reader.txt'))]})
 counts=collections.Counter()
 for line in gzip.decompress((ROOT/'identity-diagnostics.jsonl.gz').read_bytes()).splitlines():
  u=json.loads(line)['source_record'];counts[(u['parent_key'],u['context'])]+=1
 for i,parent in enumerate(d['all_unit_order']):
  assert d['native_constituents'][i]['parent_key']==parent['key']
  directory_path=STATE/f"data/turnout/source/supervisor-{parent['source_county_code']}.receipt.json"
  directory=json.load(open(directory_path));directory_body=STATE/f"data/turnout/source/supervisor-{parent['source_county_code']}.body.gz"
  text=gzip.decompress(directory_body.read_bytes()).decode(errors='replace');homes=re.findall(r'<a[^>]*href=[\"\'](https?://[^\"\']+)[\"\'][^>]*>\s*(https?://[^<]+)',text,re.I)
  home=html.unescape(homes[0][0]) if homes else None
  row={'frozen_parent':parent,'official_home_from_retained_DOS_directory':home,'directory_reference':{'receipt':str(directory_path.relative_to(STATE)),'receipt_sha256':sha(directory_path.read_bytes()),'body':str(directory_body.relative_to(STATE)),'body_stored_sha256':sha(directory_body.read_bytes()),'full_original_receipt':directory},'frozen_full_constituents_reference':{'path':'frozen-contract.semantic.json.gz','json_pointer':f'/native_constituents/{i}'},'all_native_context_counts':{c:counts[(parent['key'],c)] for c in d['complete_coverage']['native_context_counts']},'all_historical_native_contexts_unallocated':True,'current_geometry_results_crosswalk':None,'november2026_approval':None,'immutable2024_election_day_map':None}
  if i<22:
   name,key,assets,authority,vintage,gap,notice=CONFIG[i];downloads=[]
   if key:
    if key in geo and geo[key].get('acquisition'):
     ac=json.load(open(ROOT/geo[key]['acquisition']));downloads += [{'source_id':b['source_id'],'path':receipts[b['source_id']]['stored_path'],'original_bytes':receipts[b['source_id']]['original_bytes'],'original_sha256':receipts[b['source_id']]['original_sha256'],'scope':'complete bounded native-CRS geometry+attributes batch'} for b in ac['batches']]
    else:downloads.append({'source_id':key,'path':receipts[key]['stored_path'],'original_bytes':receipts[key]['original_bytes'],'original_sha256':receipts[key]['original_sha256'],'scope':'original Census2020 fallback ZIP' if name=='Duval' else 'original linked vendor map export'})
   for a in assets:downloads.append({'source_id':a,'path':receipts[a]['stored_path'],'original_bytes':receipts[a]['original_bytes'],'original_sha256':receipts[a]['original_sha256'],'scope':'historical official PDF; read-only shared original reference' if a=='duval-archived-countywide-pdf' else 'official raster render' if a=='volusia-official-render' else 'official source original'})
   preview=pdfs['duval-archived-countywide-pdf']['pages'][0]['preview_path'] if name=='Duval' else receipts['volusia-official-render']['stored_path'] if name=='Volusia' else geo[key]['preview']['PNG'] if key else pdfs[assets[0]]['pages'][0]['preview_path']
   row.update(map_status='historical official precinct-overlay PDF acquired by archive; separate Census2020 fallback; current approval unresolved' if name=='Duval' else 'actual county or officially linked asset downloaded; approval unresolved',geometry_source_key=key,source_geometry_feature_count=geo[key]['feature_count'] if key else None,geometry_source_scope='separate Census2020 fallback; not measured PDF precinct count' if name=='Duval' else 'native/display source geometry snapshot' if key else None,official_reference_acquired=True,authority_source_id=authority,authority_url=receipts[authority]['request_url'],vintage_evidence=vintage,specific_gap=gap,change_investigation_source_id=notice,downloads=downloads,preview=preview)
  else:row.update(map_status='remainder: current map not acquired in priority assignment',geometry_source_key=None,source_geometry_feature_count=None,authority_source_id=None,authority_url=None,vintage_evidence=None,specific_gap=f"{parent['name']}: no 2024 frozen/current2026 finer-unit map acquisition in this assignment; complete historical/source/admin objects retained.",downloads=[],preview=None)
  inventory.append(row)
 json_dump(ROOT/'inventory.json',{'ordered_priority_keys':d['ordered_priority_keys'],'full67_inventory':inventory,'priority22_official_references_including_historical_Duval':True,'Duval_Census2020_fallback_separate':True,'remainder45_explicit':True,'all_native23532_preserved':'frozen-contract.semantic.json.gz and identity-diagnostics.jsonl.gz','no_geometry_join':True})
 # Download manifest records actual source entities, not result joins.
