 # Complete peer-reference object retained; raw originals stay read-only at coordinator-pinned paths.
 peer_path=STATE/'data/coordinator-current-source-review.json';peer=json.load(open(peer_path));json_dump(ROOT/'peer-compatibility-reference.json',{'review_path':str(peer_path.relative_to(STATE)),'review_sha256_at_read':sha(peer_path.read_bytes()),'full_coordinator_review':peer,'role':'Informational source scope only, not an independent acquisition or map dependency. No protected/null result cell is numeric; Lake1–29 dash banner not applied to Pinellas protected literals. No map/native/current join, method assignment, write-in allocation or cadence inferred.'})
 rows=[];cards=[]
 for i,row in enumerate(inventory[:22]):
  p=row['frozen_parent'];name=p['name'];key=row['geometry_source_key'];preview=row['preview'];downloads=' '.join(f'<a href="{html.escape(x["path"])}">{html.escape(x["source_id"])}</a>' for x in row['downloads'])
  extra=f'<a href="geometry/{key}.json">full geometry diagnostics</a>' if key else 'PDF original; vector topology unassessed'
  if name=='Volusia':extra+=' · <a href="previews/volusia.svg">linear-only SVG (31 curves omitted from preview)</a>'
  if name=='Orange':extra+=' · <a href="orange-2024.acquisition.json">separate complete2024-labeled batch index</a> · <a href="previews/orange-2024.svg">2024 preview</a>'
  if name=='Hillsborough':extra+=' · <a href="geometry/hillsborough-shp-alt.json">original ZIP/SHP/SHX/DBF checks</a>'
  if name=='Duval':extra='separate Census fallback: '+extra+' · <a href="previews/duval-census2020-vtd.svg">Census2020 fallback preview</a> · <a href="raw/duval-archived-countywide-pdf.receipt.json">immutable shared PDF provenance</a> · <a href="raw/duval-cdx-1141.receipt.json">complete archive catalog reference</a>'
  cards.append(f'<article id="county-{p["fips"]}" data-key="{p["key"]}"><h2>{i+1}. {html.escape(name)}</h2><img src="{preview}" alt="{html.escape(name)} map preview"><p class="status">{html.escape(row["map_status"])}</p><p>{html.escape(row["vintage_evidence"])}</p><p>{html.escape(row["specific_gap"])}</p><p><a href="{row["authority_url"]}">Primary authority</a> · {extra}</p><details><summary>Download all {len(row["downloads"])} original entities</summary><p class="downloads">{downloads}</p></details></article>')
  rows.append(f'<tr data-key="{p["key"]}"><td>{p["rank"]}</td><td>{html.escape(name)}</td><td>{p["fips"]}</td><td>{p["votes"]:,}</td><td>{html.escape(row["map_status"])}</td><td>'+(' / '.join(f'{html.escape(c)}: {n}' for c,n in row['all_native_context_counts'].items()))+'</td></tr>')
 for row in inventory[22:]:
  p=row['frozen_parent'];rows.append(f'<tr data-key="{p["key"]}"><td>{p["rank"]}</td><td>{html.escape(p["name"])}</td><td>{p["fips"]}</td><td>{p["votes"]:,}</td><td>Remainder — map not acquired; all source contexts retained</td><td>'+' / '.join(f'{html.escape(c)}: {n}' for c,n in row['all_native_context_counts'].items())+'</td></tr>')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Florida precinct map evidence</title><style>body{font:16px/1.5 system-ui,sans-serif;color:#172435;background:#eef2f6;margin:0}main{max-width:1240px;margin:auto;padding:28px}a{color:#075c92}h1{font-size:32px;line-height:1.15}h2{font-size:22px}header,.note{background:white;padding:24px;border-radius:12px;margin-bottom:22px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:20px}article{background:white;padding:20px;border-radius:12px;overflow:hidden}article img{display:block;width:100%;height:360px;object-fit:contain;background:#f6f7f9}article p{font-size:14px}.status{font-weight:650}.downloads a{display:block;overflow-wrap:anywhere}table{background:white;border-collapse:collapse;font-size:13px;width:100%}th,td{padding:9px;border-bottom:1px solid #d9e0e8;text-align:left;vertical-align:top}.scroll{overflow:auto}details{padding:10px;background:#f2f5f7}summary{cursor:pointer}footer{margin:24px 0;font-size:13px}</style><main><header><h1>Florida precinct map evidence</h1><p>October 18, 2026 archival research. The exact 22-county historical priority contributes <strong>8,734,473 / 10,757,428 = 81.19480790389673%</strong> of valid/named2024 Senate votes. All67 counties remain in arithmetic.</p><p><strong>All22 priority counties have official or officially linked map references. Duval uses a historical official precinct-overlay PDF archived January6,2026; its Census2020 VTD fallback remains separate.</strong> None is certified here as an approved November2026 reporting crosswalk or frozen2024 election-day map. Feature counts are source geometry counts; no votes or methods are assigned to polygons.</p><p><a href="inventory.json">Full67 inventory</a> · <a href="source-ledger.json">Original/error acquisition ledger</a> · <a href="frozen-contract.semantic.json.gz">Complete frozen semantic contract</a> · <a href="identity-diagnostics.jsonl.gz">Full23,532-context diagnostics</a> · <a href="validation.json">Offline validation</a> · <a href="asset-manifest.json">Complete file manifest</a></p></header><div class="grid">'''+''.join(cards)+'''</div><section class="note"><h2>Complete PDF previews and source defects</h2><p>All89 pages of14 original PDFs rendered. Originals remain unchanged. PDF and vector defects are recorded; thumbnails are research aids. Volusia's official raster preserves a view of curved geometry; its separate linear SVG is explicitly incomplete.</p><p><a href="pdf-render-validation.json">PDF render metadata and warnings</a> · <a href="geometry-summary.json">Native CRS, precision, counts and defects</a></p>'''+''.join(f'<a href="{x}">PDF contact sheet{i+1}</a> · ' for i,x in enumerate(pdf['contact_sheets']))+'''</section><h2>All67 counties, in frozen order</h2><p>45 remainder counties supply2,022,955 votes; their full constituent/source/admin objects are preserved. No remainder map acquisition is implied.</p><div class="scroll"><table id="all-counties"><thead><tr><th>Rank</th><th>County</th><th>FIPS</th><th>2024 valid/named Senate votes</th><th>Map status</th><th>Full historical native context counts</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><footer>Static offline page: local images and downloads, no remote embeds, scripts, analytics, basemap tiles or web fonts. External primary-source citations are ordinary links. SVG/PNG display transforms do not alter native original coordinates, attributes, source order or unknown units.</footer></main></html>'''
 (ROOT/'index.html').write_text(page)
 # Selected previews contact sheet includes one actual entry per priority county, exact order.
 contact=Image.new('RGB',(1200,((22+3)//4)*250),'#d9e0e8');draw=ImageDraw.Draw(contact)
 for i,r in enumerate(inventory[:22]):
  im=Image.open(ROOT/r['preview']).convert('RGB');im.thumbnail((290,215));x=(i%4)*300;y=(i//4)*250;contact.paste(im,(x+(300-im.width)//2,y+30));draw.text((x+8,y+6),f'{i+1}. {r["frozen_parent"]["name"]}',fill='black')
 contact.save(ROOT/'previews/priority22-contact.png')
 print('inventory67; ordered22; downloads',sum(len(r['downloads']) for r in inventory))
